internal static class JagoSuiteBootstrap
{
    internal static readonly string Root=Environment.GetEnvironmentVariable("JAGO_SUITE_ROOT")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago Studio Suite");
    internal static string WorkspaceProfile {get{return Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ROOT");}}
    internal static string Pipe(string key){key+=WorkspaceProfile==null?"":"."+Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ID");string isolated="";if(Environment.GetEnvironmentVariable("JAGO_SUITE_ROOT")!=null){using(var sha=SHA256.Create())isolated="."+BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Root))).Replace("-","").Substring(0,12);}return "JagoSuite."+WindowsIdentity.GetCurrent().User.Value.Replace('-','_')+isolated+"."+key;}
    internal static string TestRoot(string[] args){for(int i=0;i<args.Length-1;i++)if(args[i]=="--suite-test")return Path.GetFullPath(args[i+1]);return null;}
    internal static string ReceivePath(string[] args){for(int i=0;i<args.Length-1;i++)if(args[i]=="--receive")return Path.GetFullPath(args[i+1]);return null;}
    internal static bool ForwardExisting(string key,string[] args){string path=ReceivePath(args);return path!=null&&Send(key,path,1200);}
    internal static bool Send(string key,string message,int timeout){try{using(var pipe=new NamedPipeClientStream(".",Pipe(key),PipeDirection.Out)){pipe.Connect(timeout);using(var writer=new StreamWriter(pipe,new UTF8Encoding(false))){writer.WriteLine(message);writer.Flush();}}return true;}catch{return false;}}
}
internal sealed class JagoSuiteHost
{
    readonly string key;readonly Form form;readonly CoreWebView2 core;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=120000000,RecursionLimit=512};
    readonly Queue<string> pending=new Queue<string>();NamedPipeServerStream listening;bool ready,closed;
    static readonly string[] Keys={"wobble","dither","repeat","worldbuilding","material","music","library"};
    static string StudioFolder(string id){return id=="music"?"Music-SFX":id=="library"?"Library-Production":char.ToUpper(id[0])+id.Substring(1);}
    static string FileName(string id){return "Jago-"+(id=="music"?"Sound":id=="library"?"Library":id=="worldbuilding"?"World":StudioFolder(id))+".exe";}
    static bool Known(string id){return Array.IndexOf(Keys,id)>=0;}
    internal JagoSuiteHost(string id,Form window,CoreWebView2 browser){key=id;form=window;core=browser;new JagoWorkspaceClient(window,browser);Directory.CreateDirectory(JagoSuiteBootstrap.Root);Register(id,Application.ExecutablePath);core.WebMessageReceived+=Message;core.NavigationCompleted+=async(s,e)=>{if(!e.IsSuccess)return;for(int i=0;i<100&&!closed;i++){if(await core.ExecuteScriptAsync("!!window.JagoSuite")=="true"){ready=true;break;}await Task.Delay(100);}if(ready){if(JagoSuiteBootstrap.TestRoot(Environment.GetCommandLineArgs())!=null)RunProbe();string initial=JagoSuiteBootstrap.ReceivePath(Environment.GetCommandLineArgs());if(initial!=null)Deliver(initial);while(pending.Count>0)Deliver(pending.Dequeue());}};form.FormClosed+=(s,e)=>{closed=true;if(listening!=null)listening.Dispose();};Task.Run((Action)Listen);}
    async void RunProbe(){string root=JagoSuiteBootstrap.TestRoot(Environment.GetCommandLineArgs());try{string probe=Path.Combine(root,"probe.js");for(int i=0;i<100&&!File.Exists(probe);i++)await Task.Delay(100);if(!File.Exists(probe))return;await core.ExecuteScriptAsync(File.ReadAllText(probe));string result="null";for(int i=0;i<1200;i++){result=await core.ExecuteScriptAsync("window.suiteTestResult||null");if(result!="null")break;await Task.Delay(100);}File.WriteAllText(Path.Combine(root,"result.json"),result);using(var file=File.Create(Path.Combine(root,"preview.png")))await core.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,file);form.Close();}catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.json"),json.Serialize(new{error=ex.ToString()}));form.Close();}}
    void Listen(){while(!closed){try{var security=new PipeSecurity();security.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.FullControl,AccessControlType.Allow));using(var pipe=new NamedPipeServerStream(JagoSuiteBootstrap.Pipe(key),PipeDirection.In,1,PipeTransmissionMode.Byte,PipeOptions.None,4096,4096,security)){listening=pipe;pipe.WaitForConnection();using(var reader=new StreamReader(pipe,Encoding.UTF8)){string request=reader.ReadLine();if(request!=null&&request.Length<32768&&!closed)form.BeginInvoke((Action)(()=>{if(request.StartsWith("ack|")){Status("Your artwork was brought into the receiving studio.");return;}if(ready)Deliver(request);else pending.Enqueue(request);}));}}}catch{if(!closed)System.Threading.Thread.Sleep(200);}}}
    Dictionary<string,string> Connections(){string file=Path.Combine(JagoSuiteBootstrap.Root,"connections.json");try{return json.Deserialize<Dictionary<string,string>>(File.ReadAllText(file));}catch{return new Dictionary<string,string>();}}
    void Register(string id,string path){var all=Connections();all[id]=path;File.WriteAllText(Path.Combine(JagoSuiteBootstrap.Root,"connections.json"),json.Serialize(all),Encoding.UTF8);}
    string Locate(string id){var all=Connections();string stored;all.TryGetValue(id,out stored);string folder=Path.GetDirectoryName(Application.ExecutablePath),best=null;Version bestVersion=new Version(0,0);foreach(string path in new[]{Path.Combine(folder,FileName(id)),Path.Combine(folder,"..",FileName(id)),Path.Combine(folder,"..",StudioFolder(id),FileName(id)),stored}){if(path==null||!ValidApp(path,id))continue;Version version;if(!Version.TryParse(FileVersionInfo.GetVersionInfo(path).FileVersion,out version))version=new Version(0,0);if(best==null||version>bestVersion){best=Path.GetFullPath(path);bestVersion=version;}}return best;}
    bool ValidApp(string path,string id){if(!File.Exists(path)||Path.GetExtension(path).ToLowerInvariant()!=".exe")return false;try{var info=FileVersionInfo.GetVersionInfo(path);var version=new Version(info.FileMajorPart,info.FileMinorPart,info.FileBuildPart);var minimum=id=="music"?new Version(0,4,0):id=="library"?new Version(0,3,0):id=="material"?new Version(0,2,0):id=="worldbuilding"?new Version(0,2,0):new Version(1,id=="wobble"?3:id=="dither"?1:7,1);return info.ProductName==(id=="music"?"Jago Music + SFX Studio":id=="library"?"Jago Library + Production Studio":"Jago "+char.ToUpper(id[0])+id.Substring(1)+" Studio") && version.CompareTo(minimum)>=0;}catch{return false;}}
    string Connect(string id){using(var picker=new OpenFileDialog{Title="Connect Jago "+id+" Studio",Filter="Jago Windows app (*.exe)|*.exe",FileName=FileName(id)}){if(picker.ShowDialog(form)!=DialogResult.OK)return null;if(!ValidApp(picker.FileName,id)){Status("Choose the current suite build of the Jago "+id+" Windows app.");return null;}Register(id,picker.FileName);Status("Studio connected. You're ready to send artwork.");return picker.FileName;}}
    void Status(string message){if(!closed)core.PostWebMessageAsJson(json.Serialize(new{type="jago-suite-status",message=message}));}
    void Deliver(string path){try{path=Path.GetFullPath(path);if(Path.GetExtension(path).ToLowerInvariant()!=".jagotransfer"||new FileInfo(path).Length>110000000)throw new Exception("Choose a Jago transfer below 110 MB.");var package=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));if(!package.ContainsKey("format")||Convert.ToString(package["format"])!="jago-studio-transfer")throw new Exception("That is not a Jago studio transfer.");core.PostWebMessageAsJson(json.Serialize(new{type="jago-suite-receive",package=package}));if(JagoSuiteBootstrap.TestRoot(Environment.GetCommandLineArgs())==null){if(form.WindowState==FormWindowState.Minimized)form.WindowState=FormWindowState.Normal;form.Show();form.Activate();}}catch(Exception e){Status("Could not receive artwork: "+e.Message);}}
    async void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){try{if(!e.Source.StartsWith(core.Source.Substring(0,core.Source.LastIndexOf('/')+1),StringComparison.OrdinalIgnoreCase))return;var m=json.Deserialize<Dictionary<string,object>>(e.WebMessageAsJson);object kind;if(!m.TryGetValue("type",out kind))return;string type=Convert.ToString(kind);if(type=="jago-workspace-action"){string workspaceRoot=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_ROOT"),action=Convert.ToString(m["action"]);if(workspaceRoot!=null&&new[]{"next","previous","home","save"}.Contains(action))File.WriteAllText(Path.Combine(workspaceRoot,"action-"+Guid.NewGuid()+".json"),json.Serialize(new{action=action}));return;}if(type=="jago-resource"){try{var result=JagoResourceShelf.Run(m);core.PostWebMessageAsJson(json.Serialize(new{type="jago-resource",id=m["id"],payload=result}));}catch(Exception err){core.PostWebMessageAsJson(json.Serialize(new{type="jago-resource",id=m["id"],error=err.Message}));}return;}if(type=="jago-suite-test-size"&&JagoSuiteBootstrap.TestRoot(Environment.GetCommandLineArgs())!=null){int width=Math.Max(850,Math.Min(1800,Convert.ToInt32(m["width"]))),height=Math.Max(650,Math.Min(1200,Convert.ToInt32(m["height"])));form.MinimumSize=new System.Drawing.Size(850,650);form.ClientSize=new System.Drawing.Size(width,height);return;}if(type=="jago-suite-test-preview"){string previewFolder=JagoSuiteBootstrap.TestRoot(Environment.GetCommandLineArgs());if(previewFolder!=null){string name=Path.GetFileName(Convert.ToString(m["name"]));if(name.EndsWith(".png"))using(var file=File.Create(Path.Combine(previewFolder,name)))await core.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,file);}return;}if(type=="jago-suite-fonts"){core.PostWebMessageAsJson(json.Serialize(new{type="jago-suite-fonts",fonts=JagoFontPool.List()}));return;}if(type=="jago-suite-test-artifact"){string testRoot=JagoSuiteBootstrap.TestRoot(Environment.GetCommandLineArgs());if(testRoot!=null){string name=Path.GetFileName(Convert.ToString(m["name"]));File.WriteAllText(Path.Combine(testRoot,name),Convert.ToString(m["text"]));}return;}if(type=="jago-suite-imported"){string source=Convert.ToString(m["source"]),id=Convert.ToString(m["id"]);Guid receipt;if(!Guid.TryParse(id,out receipt)||!Known(source))return;string receiptFolder=Path.Combine(JagoSuiteBootstrap.Root,"Receipts");Directory.CreateDirectory(receiptFolder);File.WriteAllText(Path.Combine(receiptFolder,receipt+".txt"),key+" received "+DateTime.UtcNow.ToString("o"));Task.Run(()=>JagoSuiteBootstrap.Send(source,"ack|"+id,500));return;}if(type=="jago-workscape-options"){JagoWorkscapeRoutes.Options(core);return;}if(type!="jago-suite-send"&&type!="jago-suite-connect")return;string target=Convert.ToString(m["target"]);if(!Known(target)||target==key)return;if(type=="jago-suite-connect"){Connect(target);return;}string text=Convert.ToString(m["text"]);if(text.Length>110000000)throw new Exception("Reduce this transfer before sending.");var package=json.Deserialize<Dictionary<string,object>>(text);if(Convert.ToString(package["format"])!="jago-studio-transfer"||Convert.ToString(package["sourceStudio"])!=key)throw new Exception("The transfer source is invalid.");Guid transfer;if(!Guid.TryParse(Convert.ToString(package["id"]),out transfer))throw new Exception("The transfer identifier is invalid.");string folder=Path.Combine(JagoSuiteBootstrap.Root,"Handoffs");Directory.CreateDirectory(folder);string path=Path.Combine(folder,transfer+".jagotransfer");File.WriteAllText(path,text,new UTF8Encoding(false));string workspace=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_ROOT");if(workspace==null&&m.ContainsKey("route")&&JagoWorkscapeRoutes.Route(m,path,key)){Status("Transfer opened in Workscape. Bring it into the destination when ready.");return;}object route;if(workspace!=null&&(!m.TryGetValue("route",out route)||Convert.ToString(route)!="window")){string destination=m.ContainsKey("route")?Convert.ToString(m["route"]):"new";File.WriteAllText(Path.Combine(workspace,"send-"+transfer+".json"),json.Serialize(new{target=target,route=destination,path=path}));Status("Artwork sent to Workspace. Choose how to bring it into the destination tab.");return;}string app=Locate(target)??Connect(target);if(app==null){Status("No studio selected. Your transfer is safe; use Save transfer file or connect the destination.");return;}Task.Run(()=>{if(JagoSuiteBootstrap.Send(target,path,800)){form.BeginInvoke((Action)(()=>Status("Artwork sent to the open "+target+" studio.")));return;}try{string launchArgs="--receive \""+path+"\"";string testBase=Environment.GetEnvironmentVariable("JAGO_SUITE_TEST_ROOT");if(testBase!=null)launchArgs+=" --suite-test \""+Path.Combine(testBase,target)+"\"";var launch=new ProcessStartInfo(app,launchArgs){UseShellExecute=false,WindowStyle=testBase==null?System.Diagnostics.ProcessWindowStyle.Normal:System.Diagnostics.ProcessWindowStyle.Hidden};foreach(string envKey in new[]{"JAGO_WORKSPACE_ROOT","JAGO_WORKSPACE_TAB_ROOT","JAGO_WORKSPACE_TAB_ID"})launch.EnvironmentVariables.Remove(envKey);Process.Start(launch);form.BeginInvoke((Action)(()=>Status("Opening "+target+" with your artwork. Choose where to bring it in.")));}catch(Exception ex){form.BeginInvoke((Action)(()=>Status("Could not open studio: "+ex.Message)));}});}catch(Exception ex){Status(ex.Message);}}
}


internal static class JagoFontPool {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=100000000};static string Folder{get{return Path.Combine(JagoSuiteBootstrap.Root,"Fonts");}}
 internal static object List(){var result=new List<object>();Directory.CreateDirectory(Folder);foreach(var file in Directory.GetFiles(Folder,"*.json")){if(result.Count>=32)break;try{var record=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));string target=Path.Combine(Folder,Path.GetFileName(Convert.ToString(record["file"])));if(File.Exists(target)&&new FileInfo(target).Length<=8000000)result.Add(new{id=Path.GetFileNameWithoutExtension(file),family=Convert.ToString(record["family"]),source=Convert.ToString(record["source"]),licence=Convert.ToString(record["licence"]),data=Convert.ToBase64String(File.ReadAllBytes(target))});}catch{}}return result;}
 internal static void Publish(string source,string family,string licence){if(!new[]{".ttf",".otf",".woff",".woff2"}.Contains(Path.GetExtension(source).ToLowerInvariant())||new FileInfo(source).Length>8000000)throw new Exception("Share a TTF, OTF, WOFF or WOFF2 font below 8 MB.");Directory.CreateDirectory(Folder);if(Directory.GetFiles(Folder,"*.json").Length>=32)throw new Exception("Shared pool holds 32 font files. Remove unused copies from the pool folder before adding more.");long total=0;foreach(var f in Directory.GetFiles(Folder))total+=new FileInfo(f).Length;if(total+new FileInfo(source).Length>64000000)throw new Exception("Shared font pool exceeds 64 MB.");string hash;using(var sha=SHA256.Create())using(var stream=File.OpenRead(source))hash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").Substring(0,16);string target=hash+Path.GetExtension(source).ToLowerInvariant();File.Copy(source,Path.Combine(Folder,target),true);File.WriteAllText(Path.Combine(Folder,hash+".json"),Json.Serialize(new{family=family.Length>100?family.Substring(0,100):family,source=Path.GetFileName(source),licence=licence??"Your font licence applies",file=target}));}
}

