 static void Atomic(string path,string text){string temp=path+".tmp";System.IO.File.WriteAllText(temp,text);if(System.IO.File.Exists(path))System.IO.File.Replace(temp,path,null);else System.IO.File.Move(temp,path);}
 async System.Threading.Tasks.Task Suspend(){try{await core.TrySuspendAsync();}catch(System.InvalidOperationException){/* Some runtimes decline suspension; the studio scripts are already paused. */}}
 async System.Threading.Tasks.Task Tick(){if(busy||stopped||form.IsDisposed)return;busy=true;try{
 if(!initialized){if(await core.ExecuteScriptAsync("!!window.JagoSession && !!window.JagoSuite?.adapter")=="true"){string recover=System.IO.Path.Combine(folder,"restore.json");if(System.IO.File.Exists(recover)){string data=System.IO.File.ReadAllText(recover);await core.ExecuteScriptAsync("window.__workspaceRestore=null;JagoSession.restore("+data+").then(()=>window.__workspaceRestore={ok:true}).catch(e=>window.__workspaceRestore={error:e.message})");string restoreStatus="null";for(int wait=0;wait<300;wait++){restoreStatus=await core.ExecuteScriptAsync("window.__workspaceRestore");if(restoreStatus!="null")break;await System.Threading.Tasks.Task.Delay(50);}if(restoreStatus=="null")throw new System.Exception("The document is still restoring. Please retry.");var restoreResult=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(restoreStatus);if(restoreResult.ContainsKey("error"))throw new System.Exception(System.Convert.ToString(restoreResult["error"]));System.IO.File.Move(recover,System.IO.Path.Combine(folder,"restored-"+System.Guid.NewGuid()+".json"));}initialized=true;Atomic(System.IO.Path.Combine(folder,"ready.json"),json.Serialize(new{ready=true,handle=form.Handle.ToInt64()}));}else return;}
 foreach(string path in System.IO.Directory.GetFiles(folder,"command-*.json").OrderBy(f=>f)){var m=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(System.IO.File.ReadAllText(path));string type=System.Convert.ToString(m["type"]);System.IO.File.Delete(path);
 if(type=="attach"){detachedWindow=false;timer.Interval=500;System.Environment.SetEnvironmentVariable("JAGO_WORKSPACE_ROOT",workspaceRoot);core.Resume();form.Visible=true;form.FormBorderStyle=System.Windows.Forms.FormBorderStyle.None;form.MinimumSize=new System.Drawing.Size(0,0);SetParent(form.Handle,new System.IntPtr(System.Convert.ToInt64(m["parent"])));SetStyle(form.Handle,-16,new System.IntPtr(0x50000000L));MoveWindow(form.Handle,0,0,System.Convert.ToInt32(m["width"]),System.Convert.ToInt32(m["height"]),true);Atomic(System.IO.Path.Combine(folder,"attached.json"),json.Serialize(new{handle=form.Handle.ToInt64()}));}
