internal static class JagoResourceShelf {
 static readonly System.Web.Script.Serialization.JavaScriptSerializer Json=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=30000000,RecursionLimit=512};
 static string Folder {get{return System.IO.Path.Combine(JagoSuiteBootstrap.Root,"Shelf");}}
 internal static object Run(System.Collections.Generic.Dictionary<string,object> message){System.IO.Directory.CreateDirectory(Folder);string op=System.Convert.ToString(message["operation"]);if(op=="list"){var records=new System.Collections.Generic.List<object>();foreach(var f in System.IO.Directory.GetFiles(Folder,"*.meta.json").Take(48))try{records.Add(Json.DeserializeObject(System.IO.File.ReadAllText(f)));}catch{}return new{items=records};}
 if(op=="publish"){string text=System.Convert.ToString(message["text"]);if(text.Length>24000000)throw new System.Exception("Use a shared item below 24 MB. Keep large projects as ordinary files.");var pack=Json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(text);if(System.Convert.ToString(pack["format"])!="jago-studio-transfer")throw new System.Exception("Unsupported shelf item");if(System.IO.Directory.GetFiles(Folder,"*.meta.json").Length>=48)throw new System.Exception("The shelf holds 48 items. Remove an unused copy first.");long bytes=System.IO.Directory.GetFiles(Folder).Sum(f=>new System.IO.FileInfo(f).Length);if(bytes+text.Length*2>160000000)throw new System.Exception("The shared shelf exceeds 160 MB. Remove unused copies first.");string key=System.Guid.NewGuid().ToString();System.IO.File.WriteAllText(System.IO.Path.Combine(Folder,key+".jagotransfer"),text);System.IO.File.WriteAllText(System.IO.Path.Combine(Folder,key+".meta.json"),Json.Serialize(new{key=key,name=System.Convert.ToString(message["name"]).Substring(0,System.Math.Min(160,System.Convert.ToString(message["name"]).Length)),studio=pack["sourceStudio"],tags=System.Convert.ToString(message["tags"]),favourite=false}));return new{key=key};}
 System.Guid id;if(!message.ContainsKey("key")||!System.Guid.TryParse(System.Convert.ToString(message["key"]),out id))throw new System.Exception("Choose a shelf item");string path=System.IO.Path.Combine(Folder,id.ToString()+".jagotransfer"),meta=System.IO.Path.Combine(Folder,id.ToString()+".meta.json");if(op=="get")return new{text=System.IO.File.ReadAllText(path)};if(op=="remove"){System.IO.File.Delete(path);System.IO.File.Delete(meta);return new{ok=true};}if(op=="favourite"){var data=Json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(System.IO.File.ReadAllText(meta));data["favourite"]=!System.Convert.ToBoolean(data["favourite"]);System.IO.File.WriteAllText(meta,Json.Serialize(data));return new{ok=true};}throw new System.Exception("Unsupported shelf action");}
}

