internal static class JagoWorkscapeRoutes {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=180000000,RecursionLimit=100};
 internal static string Find(){string folder=Path.GetDirectoryName(Application.ExecutablePath);var candidates=new List<string>{Path.Combine(folder,"Jago-Workscape.exe"),Path.Combine(folder,"..","Jago-Workscape.exe"),Path.Combine(folder,"..","Workscape","Jago-Workscape.exe"),Path.Combine(folder,"..","Workspace","Jago-Workscape.exe"),@"C:\Jago Studio Dev\Studios\Workspace\Jago-Workscape.exe"};try{var c=Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(JagoSuiteBootstrap.Root,"connections.json")));if(c.ContainsKey("workspace")&&String.Equals(Path.GetFileName(c["workspace"]),"Jago-Workscape.exe",StringComparison.OrdinalIgnoreCase))candidates.Insert(0,c["workspace"]);}catch{}return candidates.FirstOrDefault(File.Exists);}
 internal static List<Dictionary<string,object>> Sessions(){var result=new List<Dictionary<string,object>>();string folder=Path.Combine(JagoSuiteBootstrap.Root,"Workspaces");if(!Directory.Exists(folder))return result;foreach(string file in Directory.GetFiles(folder,"*.json")){try{var s=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));var process=Process.GetProcessById(Convert.ToInt32(s["pid"]));if(process.HasExited||!String.Equals(process.MainModule.FileName,Convert.ToString(s["exe"]),StringComparison.OrdinalIgnoreCase)||!Directory.Exists(Convert.ToString(s["session"])))continue;result.Add(s);}catch{}}return result;}
 internal static void Options(CoreWebView2 core){var tabs=new List<object>();foreach(var session in Sessions()){try{var inventory=Json.Deserialize<System.Collections.ArrayList>(File.ReadAllText(Path.Combine(Convert.ToString(session["session"]),"inventory.json")));foreach(Dictionary<string,object> tab in inventory)if(!Convert.ToBoolean(tab["detached"]))tabs.Add(new{id=tab["id"],session=session["id"],studio=tab["studio"],name=tab["name"]});}catch{}}core.PostWebMessageAsJson(Json.Serialize(new{type="jago-workscape-options",available=Find()!=null||Sessions().Count>0,tabs=tabs}));}
 internal static bool Route(Dictionary<string,object> message,string transfer,string source){string route=Convert.ToString(message["route"]);if(route!="workspace"&&route!="both"&&!route.StartsWith("workspace|",StringComparison.Ordinal))return false;var sessions=Sessions();Dictionary<string,object> selected=null;string targetTab="new";if(route.StartsWith("workspace|",StringComparison.Ordinal)){var parts=route.Split('|');if(parts.Length!=3)throw new Exception("Choose the Workscape destination again.");selected=sessions.FirstOrDefault(s=>Convert.ToString(s["id"])==parts[1]);if(selected==null)throw new Exception("That Workscape has closed. Choose a new Workscape tab.");targetTab=parts[2];}else selected=sessions.LastOrDefault();object sourceDocument=null;if(route=="both"){object captured;if(!message.TryGetValue("sourceDocument",out captured)||captured==null)throw new Exception("The current project could not be captured. It has stayed open.");var snapshot=captured as Dictionary<string,object>;if(snapshot==null||Convert.ToString(snapshot["studio"])!=source||!snapshot.ContainsKey("document"))throw new Exception("The source project snapshot is invalid.");sourceDocument=snapshot["document"];}string folder=Path.Combine(JagoSuiteBootstrap.Root,"Handoffs");Directory.CreateDirectory(folder);string job=Path.Combine(folder,Guid.NewGuid()+".jagohandoff");var payload=new{action="handoff",target=message["target"],route=targetTab,path=transfer,sourceStudio=source,sourceExe=Application.ExecutablePath,sourceDocument=sourceDocument};string text=Json.Serialize(payload);File.WriteAllText(job,text,new UTF8Encoding(false));if(selected!=null){string session=Convert.ToString(selected["session"]),action=Path.Combine(session,"action-"+Guid.NewGuid()+".json");File.WriteAllText(action+".tmp",text,new UTF8Encoding(false));File.Move(action+".tmp",action);}else{string app=Find();if(app==null)throw new Exception("Workscape is unavailable. Your transfer is saved; choose a separate window or save the transfer.");var start=new ProcessStartInfo(app,"--handoff \""+job+"\""){UseShellExecute=false,WindowStyle=ProcessWindowStyle.Hidden};if(Environment.GetEnvironmentVariable("JAGO_SUITE_ROOT")!=null)start.EnvironmentVariables["JAGO_SUITE_ROOT"]=JagoSuiteBootstrap.Root;Process.Start(start);}return true;}
}
